        _ => new[] {
            new Choice("eu-west-1", "eu-west-1") { Badge = RichText.Plain("12 ms"), Description = "Dublin" },
            new Choice("eu-central-1", "eu-central-1") { Badge = RichText.Plain("9 ms"), Description = "Frankfurt" },
